 <aside class="panel right" id="rightPanel"><div class="panel-head"><div class="eyebrow">World observer</div><div class="panel-title">The living chronicle</div></div><div class="tabs"><button class="selected" data-panel="chronicle">Chronicle</button><button data-panel="settlement">Settlement</button><button data-panel="society">Society</button></div><div class="right-content" id="observerContent"></div></aside>
 </main><div class="mobile-bottom"><button id="observeBtn">◉ Observe</button></div><div class="toast" id="toast"></div></div>
 <div class="modal-backdrop" id="modalBackdrop"><div class="modal"><div class="modal-head"><h2 id="modalTitle">World</h2><button class="modal-close" id="modalClose">✕</button></div><div class="modal-body" id="modalBody"></div></div></div>
 <script>
+const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function RNG(seed){this.s=seed>>>0;this.next=()=>{this.s=(this.s*1664525+1013904223)>>>0;return this.s/4294967296};this.int=(a,b)=>a+Math.floor(this.next()*(b-a+1));this.pick=a=>a[Math.floor(this.next()*a.length)]}
+const names=['Mira','Tomas','Neri','Asha','Oren','Lio','Sena','Bram','Iven','Kest','Runa','Edda','Corin','Vale','Tavi','Suri','Ansel','Pella','Jori','Nima','Rell','Eska','Daro','Lune','Hale','Maren','Ilya','Ossa','Perrin','Yara'];
+const surnames=['Moss','Thorn','Reed','Bell','Ash','Vale','Brook','Pine','Wren','Hearth','Fern','Stone'];
+const jobs=['forager','farmer','builder','herbalist','hunter','weaver','trader','carpenter','shepherd','healer','miller','scout'];
+const seasons=['SPRING','SUMMER','AUTUMN','WINTER'];
+const worldNames=['The Bracken Reach','Morrowfen','The Amber March','Sablewater','The Quiet Vale','Elderwake'];
+const tileColors={ocean:'#284957',deep:'#203d49',beach:'#bdac7b',grass:'#6f8b58',forest:'#426849',jungle:'#3c6952',mountain:'#777e73',snow:'#bcc4b9',desert:'#b89963',marsh:'#637e69',village:'#bd9e68',road:'#927c57',river:'#4f9aab'};
+let G;
+function makeWorld(seed){const r=new RNG(seed),w=64,h=48,tiles=[];let cx=32+r.int(-7,7),cy=24+r.int(-5,5);
+ for(let y=0;y<h;y++)for(let x=0;x<w;x++){let nx=(x-cx)/(w*.47),ny=(y-cy)/(h*.48),island=1-(nx*nx+ny*ny);let n=Math.sin(x*.31+seed*.0001)*.10+Math.cos(y*.25-seed*.0002)*.10+Math.sin((x+y)*.16)*.08+(r.next()-.5)*.24;let elev=island+n;let t=elev<-.17?'ocean':elev<-.08?'deep':elev<-.015?'beach':elev>.55?'mountain':'grass';let rain=Math.sin(y*.19+seed)*.35+Math.cos(x*.17)*.25+r.next()*.45;let temp=1-Math.abs(y-h/2)/(h*.65)+Math.sin(x*.14)*.16;if(t==='grass'){if(temp<.25)t='snow';else if(temp<.4&&rain<.45)t='mountain';else if(rain<.28)t='desert';else if(rain>.72)t=temp>.65?'jungle':'forest';else if(rain>.6)t='marsh'}tiles.push({x,y,t,food:Math.round((rain+(t==='forest'?.28:0))*5),resource:r.pick(['wood','stone','herbs','fiber','clay'])})}
+ // winding river and cultivated settlement basin
+ let rx=0;for(let y=3;y<h-3;y++){rx=clamp(rx+Math.sin(y*.22+seed)*.8+r.next()*1.8-0.9,10,w-10);let q=tiles[y*w+Math.round(rx)];if(q.t!=='ocean'&&q.t!=='deep')q.t='river'}
+ let sx=clamp(cx+r.int(-10,10),14,w-14),sy=clamp(cy+r.int(-8,8),12,h-12);for(let dy=-2;dy<=2;dy++)for(let dx=-3;dx<=3;dx++){let t=tiles[(sy+dy)*w+sx+dx];if(t&&['grass','marsh','forest'].includes(t.t))t.t=(Math.abs(dx)<2&&Math.abs(dy)<2)?'village':'road'}
+ const people=[];let id=1;for(let i=0;i<42;i++){let p={id:id++,name:`${r.pick(names)} ${r.pick(surnames)}`,age:r.int(16,68),job:r.pick(jobs),traits:r.pick([['curious','patient'],['bold','restless'],['kind','observant'],['ambitious','stubborn'],['wary','resourceful'],['creative','sociable']]),health:r.int(58,100),happiness:r.int(35,90),wealth:r.int(3,45),x:clamp(sx+r.int(-8,8),0,w-1),y:clamp(sy+r.int(-7,7),0,h-1),family:[],memory:r.pick(['A long winter taught them thrift.','They remember the river flood.','A stranger once shared their last meal.','Their mother taught them to read the clouds.','They dream of seeing the coast.']),alive:true,home:'Hearthmere'};people.push(p)}
+ for(let i=0;i<people.length;i++){if(i>0&&i%5===0){people[i].family.push(people[i-1].id);people[i-1].family.push(people[i].id)}}
+ const player={name:'Rowan Vale',age:24,health:92,hunger:22,thirst:18,stamina:88,happiness:72,wealth:12,food:3,wood:1,herbs:1,day:1,x:sx+2,y:sy+2,action:'Explore',reputation:0,inventory:{}};
+ return {seed,w,h,tiles,people,player,day:1,season:0,year:1,worldName:r.pick(worldNames),settlement:{name:'Hearthmere',population:42,food:184,wood:76,stone:41,prosperity:63,stability:76,health:72,knowledge:12,buildings:8,fields:4,market:14,government:'Village council'},events:[],zoom:1,cam:{x:0,y:0},view:'world',panel:'chronicle',selected:null,paused:false,speed:1,eco:{forest:71,wildlife:66,water:82,soil:75},weather:'Mild skies',offlineAt:Date.now(),won:false};
+}
+function addEvent(text,type='normal'){G.events.unshift({day:G.day,text,type});G.events=G.events.slice(0,40)}
+function save(){try{G.offlineAt=Date.now();localStorage.setItem('livingWorldSave',JSON.stringify(G));toast('World saved to this device')}catch(e){toast('Could not save this world')}}
+function load(){try{let s=localStorage.getItem('livingWorldSave');if(s){G=JSON.parse(s);return true}}catch(e){}return false}
+function newGame(){const seed=Math.floor(Math.random()*999999)+1;G=makeWorld(seed);addEvent('The first spring of Hearthmere begins beside the old river.','important');addEvent(`${G.settlement.population} people call this valley home.`);addEvent(`${G.people[0].name} starts work as a ${G.people[0].job}.`);G.player.x+=2;G.player.y+=1;G.offlineAt=Date.now();renderAll()}

