function newGame(){const seed=Math.floor(Math.random()*999999)+1;G=makeWorld(seed);addEvent('The first spring of Hearthmere begins beside the old river.','important');addEvent(`${G.settlement.population} people call this valley home.`);addEvent(`${G.people[0].name} starts work as a ${G.people[0].job}.`);G.player.x+=2;G.player.y+=1;G.offlineAt=Date.now();renderAll()}
function aliveCount(){return G.people.filter(p=>p.alive).length}
function dailyTick(){G.day++;G.player.hunger=clamp(G.player.hunger+12,0,100);G.player.thirst=clamp(G.player.thirst+16,0,100);G.player.stamina=clamp(G.player.stamina-6,0,100);G.player.happiness=clamp(G.player.happiness+(G.player.hunger>75?-4:0)+(G.player.health>70?1:0),0,100);let s=G.settlement, season=Math.floor((G.day-1)/24)%4;G.season=season;G.year=1+Math.floor((G.day-1)/96);s.food=Math.max(0,s.food+Math.round(s.fields*(G.eco.soil/100)*1.5)-Math.ceil(s.population*.7));s.wood=Math.max(0,s.wood+(season===2?3:1)-Math.floor(s.population/80));s.prosperity=clamp(s.prosperity+(s.food>s.population*2?1:-1),0,100);s.stability=clamp(s.stability+(s.food<s.population? -3:1)+(s.prosperity<25?-2:0),0,100);
 for(const p of G.people){if(!p.alive)continue;p.age+=1/365;p.health=clamp(p.health+(s.food<15?-1.4:.12)+(G.weather==='Drought'&&p.job==='farmer'?-1:0),0,100);p.happiness=clamp(p.happiness+(s.food<s.population?-3:((p.job==='farmer'&&season===1)?2:0))+(p.wealth>15?1:0),0,100);p.wealth=clamp(p.wealth+(p.job==='trader'?2:1)-1,0,999);if(p.health<=0||p.age>80&&Math.random()<.03){p.alive=false;addEvent(`${p.name} died at age ${Math.floor(p.age)}. The village remembers.`, 'danger');s.population=Math.max(1,s.population-1)}}
 if(G.day%3===0){let candidates=G.people.filter(p=>p.alive&&p.age>18&&p.age<38);if(candidates.length>1&&s.food>35&&Math.random()<.2){let child={id:Math.max(...G.people.map(p=>p.id))+1,name:`${names[Math.floor(Math.random()*names.length)]} ${candidates[0].name.split(' ').pop()}`,age:0,job:'apprentice',traits:[...candidates[0].traits],health:100,happiness:75,wealth:0,x:candidates[0].x,y:candidates[0].y,family:[candidates[0].id],memory:'Born in a year of plenty.',alive:true,home:s.name};G.people.push(child);candidates[0].family.push(child.id);s.population++;s.food-=8;addEvent(`${child.name} is born to the ${child.home} community.`,'important')}}
 if(G.day%7===0){let chance=Math.random();if(chance<.12){G.weather='Drought';G.eco.soil=clamp(G.eco.soil-5,10,100);G.eco.water=clamp(G.eco.water-9,8,100);s.fields=Math.max(1,s.fields-1);addEvent('A dry wind settles over the valley. The harvest falters; food stores begin to thin.','danger')}else if(chance<.2){G.weather='Gentle rain';G.eco.water=clamp(G.eco.water+4,0,100);s.fields++;addEvent('Rain returns. Garden plots flourish along the river.','important')}else G.weather='Mild skies';
 if(s.food<14){s.prosperity=clamp(s.prosperity-5,0,100);s.stability=clamp(s.stability-4,0,100);G.people.filter(p=>p.alive).forEach(p=>p.happiness=clamp(p.happiness-3,0,100));if(Math.random()<.45)addEvent(`Food scarcity raises market prices in ${s.name}; anxious families consider leaving.`,'danger')}
 if(s.stability<35&&Math.random()<.35){s.government='Emergency council';s.stability=clamp(s.stability+12,0,100);addEvent('A crowded assembly demands a new grain-sharing law. The council yields after a tense debate.','important')}
 if(s.food>90&&s.population>45&&Math.random()<.4){s.buildings++;s.fields++;s.food-=12;addEvent(`Neighbors raise a new granary and open fields beyond ${s.name}.`,'important')}
 if(G.eco.forest<30&&Math.random()<.22)addEvent('With nearby timber scarce, builders travel farther into the old forest.');
 }
 if(G.day%24===0){G.year++;addEvent(`Another year turns. The ${seasons[season]} rains have passed.`,'important');if(G.year%4===0){s.knowledge++;addEvent(`Shared craft knowledge deepens: ${s.name} now knows ${s.knowledge} useful techniques.`)}}
 if(G.player.hunger>90||G.player.thirst>92){G.player.health=clamp(G.player.health-5,0,100);if(G.player.health<=0){addEvent('You collapse from neglect. A neighbor brings you to the village healer.','danger');G.player.health=35;G.player.x=G.people[0].x;G.player.y=G.people[0].y}}
 updateDate();renderAll()}
function advance(days=1){for(let i=0;i<days;i++)dailyTick()}
function updateDate(){$('#dateChip').textContent=`${seasons[Math.floor((G.day-1)/24)%4]} · YEAR ${1+Math.floor((G.day-1)/96)}`}
let cvs=$('#worldCanvas'),ctx=cvs.getContext('2d'),cell=30,drag=null,lastMove=0;
function resizeCanvas(){let b=cvs.getBoundingClientRect(),d=window.devicePixelRatio||1;cvs.width=Math.round(b.width*d);cvs.height=Math.round(b.height*d);ctx.setTransform(d,0,0,d,0,0);if(!G.cam.initialized){let w=b.width,h=b.height;G.cam.x=G.player.x*cell-w/2;G.cam.y=G.player.y*cell-h/2;G.cam.initialized=true}drawWorld()}
function drawWorld(){if(!G||!ctx)return;let b=cvs.getBoundingClientRect(),w=b.width,h=b.height;if(!w||!h)return;ctx.clearRect(0,0,w,h);cell=clamp(28*G.zoom,14,54);let ox=G.cam.x,oy=G.cam.y;ctx.fillStyle='#182a30';ctx.fillRect(0,0,w,h);let x0=Math.max(0,Math.floor(ox/cell)),y0=Math.max(0,Math.floor(oy/cell)),x1=Math.min(G.w,Math.ceil((ox+w)/cell)),y1=Math.min(G.h,Math.ceil((oy+h)/cell));
 for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let t=G.tiles[y*G.w+x].t,px=x*cell-ox,py=y*cell-oy;ctx.fillStyle=tileColors[t]||'#65835a';ctx.fillRect(px,py,cell+.6,cell+.6);let v=(x*17+y*31+G.seed)%13;if(['forest','jungle','marsh'].includes(t)){ctx.fillStyle=t==='jungle'?'#345944':'#527451';ctx.beginPath();ctx.arc(px+cell*(.25+(v%3)*.2),py+cell*.55,cell*.17,0,7);ctx.fill();ctx.beginPath();ctx.arc(px+cell*.68,py+cell*.32,cell*.13,0,7);ctx.fill()}else if(t==='mountain'||t==='snow'){ctx.fillStyle=t==='snow'?'#d6ddd1':'#a3a99b';ctx.beginPath();ctx.moveTo(px+cell*.18,py+cell*.82);ctx.lineTo(px+cell*.5,py+cell*.17);ctx.lineTo(px+cell*.84,py+cell*.82);ctx.fill();ctx.fillStyle=t==='snow'?'#eef0e8':'#737c71';ctx.beginPath();ctx.moveTo(px+cell*.5,py+cell*.17);ctx.lineTo(px+cell*.61,py+cell*.57);ctx.lineTo(px+cell*.43,py+cell*.52);ctx.fill()}else if(t==='village'){ctx.fillStyle='#e2c992';ctx.fillRect(px+cell*.25,py+cell*.28,cell*.48,cell*.47);ctx.fillStyle='#78563a';ctx.beginPath();ctx.moveTo(px+cell*.17,py+cell*.34);ctx.lineTo(px+cell*.49,py+cell*.08);ctx.lineTo(px+cell*.81,py+cell*.34);ctx.fill()}else if(t==='road'){ctx.fillStyle='#ad9569';ctx.fillRect(px,py+cell*.39,cell,cell*.22)}else if(t==='river'){ctx.fillStyle='#78bdc5';ctx.fillRect(px+cell*.25,py,cell*.38,cell)}}
 // ambient animals and settlement markers
 let seedr=new RNG(G.seed+G.day);for(let i=0;i<20;i++){let x=seedr.int(0,G.w-1),y=seedr.int(0,G.h-1),t=G.tiles[y*G.w+x].t;if(['forest','grass','marsh'].includes(t)){let px=x*cell-ox,py=y*cell-oy;if(px>-cell&&py>-cell&&px<w&&py<h){ctx.fillStyle='#d38b68';ctx.beginPath();ctx.arc(px+cell/2,py+cell/2,Math.max(2,cell*.09),0,7);ctx.fill()}}}
 for(let p of G.people){if(!p.alive)continue;let px=p.x*cell-ox+cell/2,py=p.y*cell-oy+cell/2;if(px<0||py<0||px>w||py>h)continue;ctx.fillStyle=p.id===G.selected?'#e7c879':'#e5e3c9';ctx.beginPath();ctx.arc(px,py,p.id===G.selected?cell*.22:cell*.14,0,7);ctx.fill();if(cell>25){ctx.fillStyle='#182119';ctx.beginPath();ctx.arc(px,py,cell*.05,0,7);ctx.fill()}}
 let px=G.player.x*cell-ox+cell/2,py=G.player.y*cell-oy+cell/2;ctx.fillStyle='#f4bf62';ctx.beginPath();ctx.arc(px,py,cell*.3,0,7);ctx.fill();ctx.strokeStyle='#fff0c4';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#3e3220';ctx.beginPath();ctx.arc(px,py,cell*.1,0,7);ctx.fill();
}

