function bar(label,value,color=''){return `<div class="stat-row"><span>${label}</span><strong>${Math.round(value)}%</strong></div><div class="meter ${color}"><i style="width:${clamp(value,0,100)}%"></i></div>`}
function renderPlayer(){let p=G.player,worldTile=G.tiles[p.y*G.w+p.x];$('#playerTitle').textContent=p.name;$('#playerPanel').innerHTML=`<div class="section"><div class="person-card"><div class="person-name">${p.name}, ${p.age}</div><div class="person-sub">Wanderer · ${G.settlement.name} outskirts</div><div class="traits"><span class="trait">Known face</span><span class="trait">${p.reputation>4?'Local favorite':'New arrival'}</span></div></div></div><div class="section"><div class="section-title">Needs & wellbeing</div>${bar('Health',p.health,p.health<35?'danger':'')}${bar('Stamina',p.stamina)}${bar('Hunger',100-p.hunger,p.hunger>65?'warn':'')}${bar('Thirst',100-p.thirst,p.thirst>65?'warn':'')}${bar('Contentment',p.happiness)}</div><div class="section"><div class="section-title">Satchel</div><div class="resources"><div class="resource"><span>Food</span><strong>◈ ${p.food}</strong></div><div class="resource"><span>Wood</span><strong>♣ ${p.wood}</strong></div><div class="resource"><span>Herbs</span><strong>✿ ${p.herbs}</strong></div><div class="resource"><span>Coin</span><strong>◉ ${p.wealth}</strong></div></div></div><div class="section"><div class="section-title">What will you do?</div><div class="action-grid"><button data-action="Explore">⌖ Explore</button><button data-action="Forage">✿ Forage</button><button data-action="Hunt">♧ Hunt</button><button data-action="Rest">☾ Rest</button><button data-action="Build">⌂ Build</button><button data-action="Talk">♡ Talk</button><button data-action="Trade">⇄ Trade</button><button data-action="Eat">◈ Eat</button></div></div><div class="notice">Today: ${worldTile.t[0].toUpperCase()+worldTile.t.slice(1)} · ${G.weather}<br><span style="color:#b4bdac">${worldTile.resource} nearby · ${worldTile.food} wild food</span></div>`}
function renderChronicle(){let events=G.events.map(e=>`<div class="event ${e.type==='important'?'important':e.type==='danger'?'danger':''}"><small>DAY ${e.day} · ${seasons[Math.floor((e.day-1)/24)%4]} ${1+Math.floor((e.day-1)/96)}</small>${e.text}</div>`).join('');return `<div class="section"><div class="section-title">Recent history <span class="pill">${G.events.length} entries</span></div><div class="feed">${events||'<div class="event">The chronicle is waiting for its first story.</div>'}</div></div>`}
function renderSettlement(){let s=G.settlement;return `<div class="section"><div class="eyebrow">A small community</div><h3 style="font-size:19px;margin:3px 0">${s.name}</h3><div class="person-sub">River settlement · ${s.government}</div></div><div class="resources"><div class="resource"><span>People</span><strong>${s.population}</strong></div><div class="resource"><span>Homes & halls</span><strong>${s.buildings}</strong></div><div class="resource"><span>Food stores</span><strong>${s.food} bags</strong></div><div class="resource"><span>Timber</span><strong>${s.wood} loads</strong></div><div class="resource"><span>Stone</span><strong>${s.stone} blocks</strong></div><div class="resource"><span>Knowledge</span><strong>${s.knowledge} crafts</strong></div></div><div class="section">${bar('Prosperity',s.prosperity)}${bar('Social trust',s.stability)}${bar('Public health',s.health)}</div><div class="section"><div class="section-title">Shared projects</div><div class="event">🌾 ${s.fields} garden plots — daily yield follows soil and rainfall.</div><div class="event">⌂ ${s.buildings} buildings — neighbors add homes when stores are healthy.</div><div class="event">◉ Market prices fluctuate with food shortages and abundance.</div></div><button id="donateBtn">Contribute 2 food · ease the shortage</button>`}
function renderSociety(){let alive=G.people.filter(p=>p.alive).sort((a,b)=>b.happiness-a.happiness),avg=Math.round(alive.reduce((n,p)=>n+p.happiness,0)/(alive.length||1)),workers={};alive.forEach(p=>workers[p.job]=(workers[p.job]||0)+1);let work=Object.entries(workers).sort((a,b)=>b[1]-a[1]).map(([j,n])=>`<div class="stat-row"><span>${j[0].toUpperCase()+j.slice(1)}</span><strong>${n}</strong></div>`).join('');return `<div class="section"><div class="eyebrow">People of ${G.worldName}</div><h3 style="font-size:18px;margin:4px 0">${alive.length} lives, one valley</h3><p class="person-sub">A handful are close enough for detailed daily simulation. Everyone else is carried by settlement-level rhythms.</p></div><div class="section"><div class="section-title">Community profile</div>${bar('Average contentment',avg)}${bar('Forest health',G.eco.forest)}${bar('Water quality',G.eco.water)}${bar('Soil fertility',G.eco.soil)}</div><div class="section"><div class="section-title">Occupations</div>${work}</div><div class="section"><div class="section-title">Known residents <span class="pill">tap to follow</span></div>${alive.slice(0,14).map(p=>`<div class="event person-link" data-person="${p.id}" style="cursor:pointer"><small>AGE ${Math.floor(p.age)} · ${p.job.toUpperCase()}</small>${p.name} · ${p.traits.join(', ')}</div>`).join('')}</div>`}
function renderObserver(){let content=G.panel==='settlement'?renderSettlement():G.panel==='society'?renderSociety():renderChronicle();$('#observerContent').innerHTML=content;$$('.tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.panel===G.panel));$$('[data-person]').forEach(el=>el.onclick=()=>inspectPerson(+el.dataset.person));let donate=$('#donateBtn');if(donate)donate.onclick=()=>{if(G.player.food<2){toast('You need 2 food to contribute');return}G.player.food-=2;G.settlement.food+=2;G.settlement.stability=clamp(G.settlement.stability+3,0,100);G.player.reputation++;addEvent(`${G.player.name} shares food with the communal store. Neighbors remember the kindness.`,'important');renderAll()}}
function renderAll(){if(!G)return;updateDate();$('#worldName').textContent=G.worldName;$('#worldMeta').textContent=`Seed ${String(G.seed).padStart(6,'0')} · ${G.settlement.population.toLocaleString()} lives`;$('#simStatus').textContent=G.paused?'Time paused':`${G.weather} · ${G.speed}× simulation`;$('#pauseBtn').textContent=G.paused?'▶':'Ⅱ';$('#speedBtn').textContent=`${G.speed}×`;renderPlayer();renderObserver();drawWorld()}

