function renderAll(){if(!G)return;updateDate();$('#worldName').textContent=G.worldName;$('#worldMeta').textContent=`Seed ${String(G.seed).padStart(6,'0')} · ${G.settlement.population.toLocaleString()} lives`;$('#simStatus').textContent=G.paused?'Time paused':`${G.weather} · ${G.speed}× simulation`;$('#pauseBtn').textContent=G.paused?'▶':'Ⅱ';$('#speedBtn').textContent=`${G.speed}×`;renderPlayer();renderObserver();drawWorld()}
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
function doAction(action){let p=G.player,tile=G.tiles[p.y*G.w+p.x],s=G.settlement;p.action=action;let msg='';
 if(action==='Forage'){if(['ocean','deep','mountain','snow'].includes(tile.t)){msg='There is little to forage here.'}else{let amount=1+Math.floor(Math.random()*Math.max(1,tile.food/3));if(tile.resource==='wood'&&['forest','jungle'].includes(tile.t)){p.wood+=amount;msg=`Gathered ${amount} timber from the treeline.`}else if(tile.resource==='herbs'){p.herbs+=amount;msg=`Found ${amount} bundles of useful herbs.`}else{p.food+=amount;msg=`Collected ${amount} food from the wild.`}G.eco.forest=clamp(G.eco.forest-(tile.t==='forest'?1:0),0,100)}}
 if(action==='Hunt'){if(G.eco.wildlife<12){msg='The nearby game has grown scarce. Let the land recover.'}else if(Math.random()<.78){let n=2+Math.floor(Math.random()*3);p.food+=n;G.eco.wildlife=clamp(G.eco.wildlife-2,0,100);msg=`A careful hunt brings ${n} food. Wildlife grows a little warier.`}else{p.health=clamp(p.health-5,0,100);msg='The hunt goes poorly; you return with a bruised arm.'}}
 if(action==='Rest'){p.stamina=clamp(p.stamina+48,0,100);p.health=clamp(p.health+8,0,100);p.hunger=clamp(p.hunger-8,0,100);p.thirst=clamp(p.thirst-10,0,100);p.happiness=clamp(p.happiness+3,0,100);msg='You rest by the river. Strength and spirits return.'}
 if(action==='Eat'){if(p.food<1){msg='Your satchel is empty. Forage or visit the market.'}else{p.food--;p.hunger=clamp(p.hunger-38,0,100);p.happiness=clamp(p.happiness+2,0,100);msg='A simple meal settles your stomach.'}}
 if(action==='Talk'){let near=G.people.filter(n=>n.alive).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(near&&Math.hypot(near.x-p.x,near.y-p.y)<9){near.affinity=(near.affinity||22)+5;near.happiness=clamp(near.happiness+2,0,100);near.memory=`A warm conversation with ${p.name} on day ${G.day}.`;p.happiness=clamp(p.happiness+4,0,100);msg=`You share a thoughtful conversation with ${near.name}. Trust grows.`;addEvent(`${p.name} and ${near.name} share a conversation beside the river.`)}else msg='No one is nearby. Travel toward Hearthmere to meet the neighbors.'}
 if(action==='Trade'){openTrade();return}
 if(action==='Build'){openBuild();return}
